SELECT cat.category_id, cat.name
FROM categories AS cat
WHERE cat.is_active = false;

SELECT p.sku, p.price
FROM products AS p
WHERE p.sku = 'SKU-00042';

SELECT count(*) AS never_asked_count
FROM customers AS c
WHERE c.marketing_opt_in IS NULL;

SELECT avg(o.shipped_at - o.order_date) AS avg_time_order_to_ship
FROM orders AS o
WHERE o.shipped_at IS NOT NULL;
